using Majorsilence.Crystal.RptEngine;
using Majorsilence.Crystal.Runtime;
using SkiaSharp;

namespace Majorsilence.Crystal.VisualRegression.Tests;

/// <summary>
/// Compares majorsilence.crystal's own PDF render against a checked-in ground-truth
/// screenshot from the real, licensed Crystal Reports engine (tests/reference-renders/,
/// generated by tools/Majorsilence.Crystal.ReferenceRenderer on a dev machine that has
/// that engine installed — see this repo's plan notes).
///
/// "Near pixel-perfect" here means a tolerant similarity score plus a diff-heatmap image
/// for human triage, not byte-identical pixels: the real engine renders via GDI+, ours via
/// SkiaSharp through a completely different RDL layout engine, so font hinting and
/// anti-aliasing will always differ somewhat even when everything is semantically correct.
///
/// First triage pass (this session) found and fixed several real render-engine crashes
/// (null-handling gaps in Style.Eval* and a null _ChartMatrix in Chart.RunPage — see
/// Majorsilence.Crystal.UI.slnx's header comment) that were previously making 4 of these
/// 6 cases fail outright rather than just score low. With those fixed, 5/6 land at
/// 93-98% similarity — <see cref="MinimumExpectedSimilarity"/> reflects that real evidence
/// now, not a guess. The one still-failing case
/// (benbrahim777__Top5USAsubCanada, page 2) is a known, un-fixed gap, left failing on
/// purpose rather than skipped/ignored — our exported PDF only has 1 page where the real
/// engine's has 2 (the subreport content isn't rendering at all), same "document the real
/// gap, don't hide it" precedent as BACKLOG.md's other open items.
/// </summary>
[TestFixture]
public class VisualRegressionTests
{
    // Evidence-based floor from this session's first triage pass (5/6 cases land at
    // 93-98%) with headroom for legitimate per-file variance — not a guess.
    private const double MinimumExpectedSimilarity = 85.0;

    [OneTimeSetUp]
    public void Init() => ReportEngine.Init();

    private static string CorpusPath(string name) =>
        Path.GetFullPath($"../../../../rpt-corpus/{name}", AppContext.BaseDirectory);

    private static string ReferencePath(string corpusStem, int pageIndex) =>
        Path.GetFullPath(
            $"../../../../reference-renders/{corpusStem}/real-crystal-page-{pageIndex + 1}.png",
            AppContext.BaseDirectory);

    [TestCase("benbrahim777__CustomerList.rpt", "benbrahim777__CustomerList", 0)]
    [TestCase("benbrahim777__SalesByCustomer-Grouped.rpt", "benbrahim777__SalesByCustomer-Grouped", 0)]
    [TestCase("benbrahim777__Top5USAsubCanada.rpt", "benbrahim777__Top5USAsubCanada", 0)]
    [TestCase("benbrahim777__Top5USAsubCanada.rpt", "benbrahim777__Top5USAsubCanada", 1)]
    [TestCase("benbrahim777__Canada-CrossTab.rpt", "benbrahim777__Canada-CrossTab", 0)]
    [TestCase("benbrahim777__Top5USA-piechart.rpt", "benbrahim777__Top5USA-piechart", 0)]
    public async Task ExportedPdf_MatchesRealCrystalReference(string corpusFile, string referenceStem, int pageIndex)
    {
        string rptPath = CorpusPath(corpusFile);
        Assume.That(File.Exists(rptPath), Is.True, $"{corpusFile} not found — run scripts/download-test-rpts.sh");

        string referencePngPath = ReferencePath(referenceStem, pageIndex);
        Assume.That(File.Exists(referencePngPath), Is.True, $"Reference image not found: {referencePngPath}");

        // No pushed overrides: matches the real-Crystal reference's own render mode
        // (Exporter.exportReportToStream with a bare Data() — whatever's saved in the .rpt).
        byte[] pdfBytes;
        using (var rpt = File.OpenRead(rptPath))
        {
            pdfBytes = await new ReportEngine().ExportAsync(rpt, new RuntimeOverrides(), ExportFormat.Pdf);
        }

        using var ourPdfStream = new MemoryStream(pdfBytes);
        using var ours = PDFtoImage.Conversion.ToImage(ourPdfStream, page: new Index(pageIndex));
        using var reference = SKBitmap.Decode(referencePngPath);

        Assert.That(ours, Is.Not.Null, "our PDF failed to rasterize");
        Assert.That(reference, Is.Not.Null, "reference PNG failed to decode");

        var (similarity, diff) = Compare(reference!, ours!);

        string outDir = Path.Combine(TestContext.CurrentContext.WorkDirectory, "visual-diffs");
        Directory.CreateDirectory(outDir);
        string diffPath = Path.Combine(outDir, $"{referenceStem}-page{pageIndex + 1}-diff.png");
        using (var fs = File.OpenWrite(diffPath))
            diff.Encode(fs, SKEncodedImageFormat.Png, 90);
        diff.Dispose();

        TestContext.Out.WriteLine($"{referenceStem} page {pageIndex + 1}: {similarity:F1}% similar. Diff written to {diffPath}");

        Assert.That(similarity, Is.GreaterThanOrEqualTo(MinimumExpectedSimilarity),
            $"{referenceStem} page {pageIndex + 1} dropped below the placeholder similarity floor — see {diffPath}");
    }

    /// <summary>
    /// Aligns dimensions (resizing our render to the reference's size — real-Crystal PDFs
    /// and ours may come out at slightly different default page-to-pixel scaling), then
    /// computes a per-pixel RGB difference. Returns a 0-100 similarity score and a
    /// red-heat diff image (brighter = more different) sized to match the reference.
    /// </summary>
    private static (double SimilarityPercent, SKBitmap Diff) Compare(SKBitmap reference, SKBitmap ours)
    {
        using SKBitmap oursResized = (reference.Width == ours.Width && reference.Height == ours.Height)
            ? ours.Copy()
            : ours.Resize(new SKImageInfo(reference.Width, reference.Height), new SKSamplingOptions(SKFilterMode.Linear));

        SKBitmap a = reference.Copy(SKColorType.Bgra8888);
        SKBitmap b = oursResized.Copy(SKColorType.Bgra8888);
        var diff = new SKBitmap(new SKImageInfo(a.Width, a.Height, SKColorType.Bgra8888));

        byte[] aBytes = a.Bytes;
        byte[] bBytes = b.Bytes;
        byte[] diffBytes = new byte[aBytes.Length];

        long totalDiff = 0;
        int pixelCount = a.Width * a.Height;
        for (int i = 0; i < pixelCount; i++)
        {
            int o = i * 4; // B, G, R, A (Bgra8888)
            int db = Math.Abs(aBytes[o] - bBytes[o]);
            int dg = Math.Abs(aBytes[o + 1] - bBytes[o + 1]);
            int dr = Math.Abs(aBytes[o + 2] - bBytes[o + 2]);
            int d = db + dg + dr;
            totalDiff += d;

            byte intensity = (byte)Math.Min(255, d);
            diffBytes[o] = 0;              // B
            diffBytes[o + 1] = 0;          // G
            diffBytes[o + 2] = intensity;  // R — brighter red = more different
            diffBytes[o + 3] = 255;        // A
        }

        System.Runtime.InteropServices.Marshal.Copy(diffBytes, 0, diff.GetPixels(), diffBytes.Length);

        double maxPossibleDiff = (double)pixelCount * 255 * 3;
        double similarity = 100.0 * (1.0 - totalDiff / maxPossibleDiff);

        a.Dispose();
        b.Dispose();
        return (similarity, diff);
    }
}
